window.QUESTIONS.push(...[{"id":"114-5-A-25","exam":"114-5","q":25,"unit":"經濟學","topic":"經濟學","stem":"下列敘述何者正確？","options":["亞當斯密(Adam Smith)著有《國富論》，馬爾薩斯(Thomas Malthus)著有《資本論》","馬歇爾(Alfred Marshall)提出需求函數，熊彼得(Joseph Schumpeter)提出乘數原理","醫學數據顯示，接種流感疫苗可以降低罹患流感併發重症的風險，此屬實證經濟學的範圍","生產可能曲線上的每一點，均代表在固定資源與技術水準下，所能達到的最高產品品質"],"answer":"B","official":"(A)《資本論》的作者為馬克思，馬爾薩斯著有《人\n口論》\n(B) 乘數原理由凱因斯所提出\n(D) 生產可能曲線上的每一點均為固定資源與技術水\n準下，生產兩種財貨所能達到的最高產量組合","scan":"data:image/webp;base64,"}]);
